OwnerDto toOwnerDto(Owner owner);

/**
 * The owner's age band, derived when a {@code birthDate} is present by counting the
 * completed years from birthDate to the effective {@code registrationDate}: 'MINOR'
 * under 18, 'ADULT' 18-64 and 'SENIOR' 65 or older. {@code null} when the owner has no
 * birthDate (or no registrationDate to compute against).
 */
default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
    java.time.LocalDate birthDate = owner.getBirthDate();
    java.time.LocalDate registrationDate = owner.getRegistrationDate();
    if (birthDate == null || registrationDate == null) {
        return null;
    }
    int years = java.time.Period.between(birthDate, registrationDate).getYears();
    if (years < 18) {
        return OwnerDto.AgeBandEnum.MINOR;
    }
    if (years < 65) {
        return OwnerDto.AgeBandEnum.ADULT;
    }
    return OwnerDto.AgeBandEnum.SENIOR;
}

